def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    if n >= 99:
        if opp_d > 0 or my_d > 0:
            return 'D'
        return 'C'

    last_me, last_opp = history[-1]

    recent_start = n - 12
    if recent_start < 0:
        recent_start = 0

    recent_opp_d = 0
    recent_my_d = 0
    for a, b in history[recent_start:]:
        if b == 'D':
            recent_opp_d += 1
        if a == 'D':
            recent_my_d += 1

    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    my_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run += 1
        else:
            break

    forgive = 0
    punish = 0

    mc_c = 0
    mc_d = 0
    md_c = 0
    md_d = 0

    oc_cc = 0
    oc_cd = 0
    oc_dc = 0
    oc_dd = 0

    start = n - 12
    if start < 1:
        start = 1

    for i in range(1, n):
        prev_my = history[i - 1][0]
        prev_opp = history[i - 1][1]
        curr_opp = history[i][1]

        if prev_my == 'D':
            if curr_opp == 'C':
                forgive += 1
            else:
                punish += 1

        if i >= start:
            if prev_my == 'C':
                if curr_opp == 'C':
                    mc_c += 1
                else:
                    mc_d += 1
            else:
                if curr_opp == 'C':
                    md_c += 1
                else:
                    md_d += 1

            if prev_opp == 'C':
                if curr_opp == 'C':
                    oc_cc += 1
                else:
                    oc_cd += 1
            else:
                if curr_opp == 'C':
                    oc_dc += 1
                else:
                    oc_dd += 1

    opp_c_rate = opp_c / float(n)

    full_total = forgive + punish
    if full_total > 0:
        full_ratio = forgive / float(full_total)
    else:
        full_ratio = 0.0

    recent_d_total = md_c + md_d
    if recent_d_total > 0:
        recent_ratio = md_c / float(recent_d_total)
    else:
        recent_ratio = 0.0

    exploit_ok = False
    if opp_c_rate > 0.6:
        if full_ratio >= 0.75 and opp_d * 3 <= n:
            if forgive >= 2 or (forgive >= 1 and punish == 0 and opp_d <= 2):
                exploit_ok = True
        if recent_ratio >= 0.75 and md_c >= 2 and opp_d * 2 <= n:
            exploit_ok = True
        if forgive >= 4 and punish == 0:
            exploit_ok = True

    if last_opp == 'D':
        if opp_d * 3 >= n * 2 or recent_opp_d >= 6:
            return 'D'

        if exploit_ok:
            return 'D'

        if recent_my_d >= 4 and opp_c_rate > 0.55 and recent_opp_d <= 4:
            return 'C'

        if punish > 0 and forgive == 0 and opp_c_rate > 0.6 and recent_opp_d <= 1:
            return 'C'

        if opp_run >= 2 and opp_d * 3 <= n and recent_my_d >= 2:
            return 'C'

        return 'D'

    if exploit_ok:
        return 'D'

    total_opp_trans = oc_cc + oc_cd
    if total_opp_trans > 0:
        p = 0.75 * (oc_cc / float(total_opp_trans + 1)) + 0.25 * opp_c_rate
    else:
        p = opp_c_rate

    total_my_c = mc_c + mc_d
    if total_my_c > 0:
        q_c = (mc_c + 1.0) / float(total_my_c + 2.0)
    else:
        q_c = opp_c_rate

    if recent_d_total > 0:
        if md_d > 0 and full_ratio < 0.75:
            q_d = 0.0
        else:
            q_d = (md_c + 0.5) / float(recent_d_total + 2.0)
        if punish > 0 and forgive == 0:
            q_d = 0.0
        if full_ratio < 0.5:
            q_d *= 0.5
    else:
        q_d = 0.0

    val_c = 3.0 * p + 1.0 + 2.0 * q_c
    val_d = 1.0 + 4.0 * p + 1.0 + 2.0 * q_d

    if val_d > val_c + 0.5:
        return 'D'

    return 'C'
